    // A new helper function or lambda to parse the log level string
    auto parse_log_level(const std::string& level_str) {
        if (level_str == "DEBUG") return spdlog::level::debug;
        if (level_str == "WARN") return spdlog::level::warn;
        if (level_str == "ERROR") return spdlog::level::err;
        // Default to INFO for security and clarity
        return spdlog::level::info;
    }

